@@ -0,0 +1,50 @@
+import { Redis } from "ioredis"
+import { createRedisClient } from "../config/redis.js"
+import { v4 as uuidv4 } from "uuid"
+
+export type ActivityEntry = {
+  id: string
+  ts: string
+  type: "step_start" | "step_done" | "phase" | "note"
+  stepId?: number
+  phase?: string
+  message: string
+  meta?: Record<string, unknown>
+}
+
+export class ActivityStore {
+  private redis: Redis
+  private TTL = 60 * 60 * 24 * 7 // 7 days
+
+  constructor() {
+    this.redis = createRedisClient()
+  }
+
+  private key(taskId: string) {
+    return `activity:${taskId}`
+  }
+
+  async append(taskId: string, entry: Omit<ActivityEntry, 'id' | 'ts'>): Promise<void> {
+    const e: ActivityEntry = { id: uuidv4(), ts: new Date().toISOString(), ...entry }
+    const key = this.key(taskId)
+    const pipeline = this.redis.pipeline()
+    pipeline.lpush(key, JSON.stringify(e))
+    pipeline.ltrim(key, 0, 99) // keep max 100
+    pipeline.expire(key, this.TTL)
+    await pipeline.exec()
+  }
+
+  async list(taskId: string, limit = 50): Promise<ActivityEntry[]> {
+    const key = this.key(taskId)
+    const end = Math.max(0, limit - 1)
+    const items = await this.redis.lrange(key, 0, end)
+    return items.map((s) => JSON.parse(s) as ActivityEntry)
+  }
+
+  async clear(taskId: string): Promise<void> {
+    await this.redis.del(this.key(taskId))
+  }
+}
+
+export default new ActivityStore()
+
